insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000049104', '$90^\circ$.', 'A questão avalia uma habilidade específica de Geometria Analítica: reconhecer a estrutura matemática antes da conta. O produto escalar combina componentes correspondentes e produz um número real. Ele conecta a álgebra à geometria por meio de ortogonalidade, ângulos, projeções e trabalho; por isso conferimos também o significado do resultado. A alternativa A respeita essa estrutura. Já a alternativa B foi incluída porque reproduz uma troca comum de ordem, sinal, direção ou interpretação; confronte-a com a definição antes de descartá-la.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000491041', '40000000-0000-4000-8000-000000049104', 'Reconheça a tarefa', 'Leia o comando e nomeie a propriedade geométrica ou operação vetorial que ele solicita.', 1), ('70000000-0000-4000-8000-000000491042', '40000000-0000-4000-8000-000000049104', 'Calcule o produto', '$u \cdot v=0.$', 2), ('70000000-0000-4000-8000-000000491043', '40000000-0000-4000-8000-000000049104', 'Use a relação angular', '$u \cdot v=|u||v|\cos \theta.$', 3), ('70000000-0000-4000-8000-000000491044', '40000000-0000-4000-8000-000000049104', 'Conclua', '$\cos \theta=0 \Rightarrow \theta=90^\circ.$', 4), ('70000000-0000-4000-8000-000000491045', '40000000-0000-4000-8000-000000049104', 'Cheque a interpretação', 'O resultado precisa satisfazer a relação original; essa verificação também elimina erros plausíveis das alternativas.', 5) on conflict (id) do update set question_id = excluded.question_id, title = excluded.title, content_markdown = excluded.content_markdown, sort_order = excluded.sort_order;
