-- Pacote calculo-vetorial-diverso: parte 1 de 3.
-- Execute cada parte uma única vez, sempre em ordem numérica.
-- Não execute depois as migrations individuais já incorporadas aqui.
-- Pré-requisito: o schema base da Arc já deve existir.
-- Ordem segura dos conjuntos: calculo-2, calculo-1, calculo-vetorial.
-- ===== 20260909180100_diversify_vector_calculus_batch_01.sql =====
-- Banco renovado de Cálculo Vetorial — lote 01: 50 questões autorais, variadas e revisadas.
-- Pré-requisito: execute 20260909160000_expand_vector_calculus_catalogue.sql e os lotes anteriores deste banco.
begin;

-- Preserva tentativas já registradas, mas tira da navegação as questões antigas do banco vetorial.
update public.questions set publication_status = 'draft' where subject_id = '20000000-0000-4000-8000-000000000003' and publication_status = 'published' and coalesce(source_id::text, '') not in ('10000000-0000-4000-8000-000000000232', '10000000-0000-4000-8000-000000000233', '10000000-0000-4000-8000-000000000234', '10000000-0000-4000-8000-000000000235', '10000000-0000-4000-8000-000000000236');

values ('10000000-0000-4000-8000-000000000232', 'original', 'Arc original Cálculo Vetorial — banco renovado, lote 01', 'Questões originais da Arc, redigidas e revisadas para diversidade de abordagem e clareza pedagógica.', 'Arc', 'approved', 'Equipe editorial Arc', '2026-09-09T00:00:00Z')
on conflict (id) do update set label = excluded.label, licence_note = excluded.licence_note, rights_status = excluded.rights_status, verified_by = excluded.verified_by, verified_at = excluded.verified_at;



















































commit;

